import java.text.DecimalFormat;
import java.util.Scanner;
public class JWinPercentage {
	public static void main(String[] args) {
		//Khatwa 1: Taareef wa tahyiat al-mutaghayyir li-takhzeen al-adad al-kulli lil-mubaarayat fi al-butula
		int totalGames = 12;
		//Khatwa 2: Qira'at al-raqam alladhi yadkhuluhu al-mustakhdim
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil adad al-mubaarayat allati faza biha al-fariq fi al-butoolah: ");
		int wins = scan.nextInt();		
		//Khatwa 3: Taqweem madaakhil al-mustakhdim, wa talab madaakhil saheehah maa duma adkhala al-mustakhdim raqam ghayr saheeh; wa illa tawqaf
		while ( wins < 0 || wins > totalGames ) {
			System.out.println("Adkhil adad al-mubaarayat allati faza biha al-fariq fi al-butoolah: ");
			wins = scan.nextInt();
		}
		scan.close();
		//Khatwa 4: Hisab wa tabaaeat nisbat al-mubaarayat allati fazaha al-fariq
		double ratio = (double) wins / totalGames;
		DecimalFormat fmt = new DecimalFormat("0.###");
		System.out.println("Nisbat al-fawz:" + fmt.format(ratio));
	}
}
